css:
.customprog-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece6da 100%);
    border-radius: 18px;
}

.customprog-container * {
    box-sizing: border-box;
}

.customprog-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #141d33 0%, #1f2c4d 55%, #2c3f6b 100%);
    color: #f6f2e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 29, 51, 0.32);
}

.customprog-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.customprog-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c884;
    background: rgba(231, 200, 132, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.customprog-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe4ef;
}

.customprog-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3f6b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.customprog-period-counter #currentDay,
.customprog-period-counter #maxPeriods {
    font-weight: 800;
    color: #141d33;
}

.customprog-round-name {
    background: #e3dccb;
    color: #5a4413;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.customprog-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a3b1a;
    background: #f6e2d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.customprog-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.customprog-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 29, 51, 0.07);
    border-top: 4px solid #2c3f6b;
}

.customprog-card-fit { border-top-color: #2c3f6b; }
.customprog-card-margin { border-top-color: #1f7a4d; }
.customprog-card-faculty { border-top-color: #8a6d1f; }
.customprog-card-launch { border-top-color: #5a4db0; }

.customprog-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #79736a;
}

.customprog-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #141d33;
}

.customprog-card-fit .customprog-value { color: #2c3f6b; }
.customprog-card-margin .customprog-value { color: #1f7a4d; }
.customprog-card-faculty .customprog-value { color: #8a6d1f; }
.customprog-card-launch .customprog-value { color: #5a4db0; }

.customprog-sublabel {
    font-size: 0.76rem;
    color: #8c857a;
    line-height: 1.35;
}

.customprog-margin-fail .customprog-value { color: #c0392b; }
.customprog-margin-ok .customprog-value { color: #1f7a4d; }

.customprog-budget-over .customprog-value { color: #c0392b; }

.customprog-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #141d33;
    color: #f1ece0;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.customprog-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c884;
}

.customprog-budget-bar.customprog-bar-over #budgetDisplay {
    color: #ff9b82;
}

.customprog-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #8a6d1f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 29, 51, 0.05);
}

.customprog-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.customprog-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #141d33;
    margin-bottom: 6px;
}

.customprog-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #38414f;
}

.customprog-briefing-text strong { color: #1f7a4d; }
.customprog-briefing-text em { color: #8a3b1a; font-style: italic; }

.customprog-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 29, 51, 0.07);
}

.customprog-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #141d33;
    border-bottom: 2px solid #ece6da;
    padding-bottom: 8px;
}

.customprog-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3140;
    margin: 14px 0 6px;
}

.customprog-container select,
.customprog-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc6b3;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f3;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.customprog-container select:focus,
.customprog-container input[type="number"]:focus {
    outline: none;
    border-color: #8a6d1f;
    box-shadow: 0 0 0 3px rgba(138, 109, 31, 0.16);
}

.customprog-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.customprog-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2c3f6b;
}

.customprog-range-readout,
.customprog-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c3f6b;
    margin-top: 4px;
}

.customprog-range-readout span:last-child,
.customprog-alloc-readout span:nth-child(2) {
    color: #1f7a4d;
    font-weight: 800;
}

.customprog-hint {
    font-size: 0.8rem;
    color: #8c857a;
    margin-top: 4px;
    line-height: 1.4;
}

.customprog-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.customprog-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f4ec;
    border: 1px solid #e6dfce;
    border-radius: 9px;
    padding: 8px 12px;
}

.customprog-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3140;
}

.customprog-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.customprog-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.customprog-container .btn-primary {
    background: linear-gradient(135deg, #1f7a4d 0%, #2c3f6b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(31, 122, 77, 0.26);
}

.customprog-container .btn-primary:hover {
    filter: brightness(1.07);
}

.customprog-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc6b3;
    color: #79736a;
}

.customprog-coach {
    background: #141d33;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 29, 51, 0.24);
}

.customprog-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c884;
    margin-bottom: 8px;
}

.customprog-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.customprog-coach-body strong { color: #f3d79a; }
.customprog-coach-body em { color: #f4b89e; font-style: italic; }

.customprog-history,
.customprog-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 29, 51, 0.07);
}

.customprog-history h3,
.customprog-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #141d33;
}

.customprog-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3140;
}

.customprog-container table#usfHistoryTable th {
    background: #f1ede3;
    color: #141d33;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2dac8;
}

.customprog-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece2;
}

.customprog-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f3;
}

.customprog-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .customprog-container {
        padding: 14px;
    }
    .customprog-header h1 {
        font-size: 1.7rem;
    }
    .customprog-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .customprog-value {
        font-size: 2rem;
    }
    .customprog-clock {
        margin-left: 0;
    }
    .customprog-period-counter {
        font-size: 0.88rem;
    }
    .customprog-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .customprog-alloc-row {
        flex-wrap: wrap;
    }
    .customprog-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .customprog-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.customprog-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #141d33; }
.customprog-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(20,29,51,0.14); margin-bottom: 16px; }
.customprog-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f7a4d; }
.customprog-cm-score-max { font-size: 18px; font-weight: 600; color: #2c3f6b; margin-left: 2px; }
.customprog-cm-grade { font-size: 18px; font-weight: 700; color: #141d33; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.customprog-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.customprog-cm-yes { background: rgba(31,122,77,0.14); color: #1a6641; }
.customprog-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.customprog-cm-warn { background: rgba(138,109,31,0.16); color: #6f5717; }
.customprog-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.customprog-cm-metric { flex: 1 1 120px; background: #faf8f3; border: 1px solid rgba(20,29,51,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.customprog-cm-mv { display: block; font-size: 24px; font-weight: 800; color: #141d33; }
.customprog-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #2c3f6b; margin-top: 2px; }
.customprog-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #2c3f6b; margin-bottom: 8px; }
.customprog-cm-insights { margin: 0; padding-left: 20px; }
.customprog-cm-insights li { font-size: 14px; line-height: 1.5; color: #2a3140; margin-bottom: 8px; }

