(function() {
    'use strict';

    class CustomProgramAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Design the Custom Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (money in € millions).
            this.BUDGET_CAP = 1.80;       // €1.8M client cap
            this.MARGIN_FLOOR = 35;       // 35% contribution-margin floor
            this.STAR_DAYS_AVAILABLE = 24; // two senior academics, 12 days each
            this.STAR_DAY_COST = 0.012;   // €12k/day (scarce, expensive)
            this.AFFILIATE_DAY_COST = 0.002; // €2k/day
            this.CLIENT_DAY_COST = 0.0;   // client execs cost nothing

            // Concept truths (the diagnosed answers).
            this.TRUE_GAP = `underlying`;
            this.TRUE_EVIDENCE = `triangulate`;
            this.TRUE_METRIC = `behaviour`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 16,
                    margin: 35,
                    faculty: 60,
                    launch: 10,
                    engagementCost: 0,   // committed cost in €M
                    price: 1.80,         // current quoted price in €M
                    starDays: 0,
                    marginAdj: null,     // scope-adjusted margin recorded in round 3
                    discounted: false,   // a round-4 price match was taken
                    overPromised: false,
                    belowFloor: false,
                    overCap: false,
                    fitHistory: [16],
                    marginHistory: [35],
                    facultyHistory: [60],
                    launchHistory: [10],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `underlying`,
                    evidence: `triangulate`,
                    behaviours: 3,
                    metric: `behaviour`,
                    format: `blended`,
                    star: 20,
                    affiliate: 40,
                    client: 16,
                    transfer: `actionproject`,
                    price: 1.80,
                    launchPlan: `phased`,
                    impactFee: `design`,
                    scope: 60,
                    value: `diagnosis`,
                    cheaper: `value`,
                    feasible: `phasedproof`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const ev = document.getElementById(`evidenceInput`);
                const bh = document.getElementById(`behavioursInput`);
                const me = document.getElementById(`metricInput`);
                if (gap) decisions.gap = gap.value;
                if (ev) decisions.evidence = ev.value;
                if (bh) decisions.behaviours = parseInt(bh.value, 10);
                if (me) decisions.metric = me.value;
                if (!Number.isFinite(decisions.behaviours) || decisions.behaviours < 0 || decisions.behaviours > 12) {
                    warn(`warn_behaviours_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                const tr = document.getElementById(`transferInput`);
                if (fmt) decisions.format = fmt.value;
                if (tr) decisions.transfer = tr.value;
                const star = document.getElementById(`starInput`);
                const aff = document.getElementById(`affiliateInput`);
                const cli = document.getElementById(`clientInput`);
                if (star) decisions.star = parseFloat(star.value);
                if (aff) decisions.affiliate = parseFloat(aff.value);
                if (cli) decisions.client = parseFloat(cli.value);
                const parts = [decisions.star, decisions.affiliate, decisions.client];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_days_negative`); return false;
                }
                if (decisions.star + decisions.affiliate + decisions.client <= 0) {
                    warn(`warn_days_zero`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`priceInput`);
                const lp = document.getElementById(`launchPlanInput`);
                const ifee = document.getElementById(`impactFeeInput`);
                const sc = document.getElementById(`scopeInput`);
                if (pr) decisions.price = parseFloat(pr.value);
                if (lp) decisions.launchPlan = lp.value;
                if (ifee) decisions.impactFee = ifee.value;
                if (sc) decisions.scope = parseInt(sc.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 1.0 || decisions.price > 2.6) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.scope) || decisions.scope < 0 || decisions.scope > 100) {
                    warn(`warn_scope_range`); return false;
                }
            } else if (round === 4) {
                const va = document.getElementById(`valueInput`);
                const ch = document.getElementById(`cheaperInput`);
                const fe = document.getElementById(`feasibleInput`);
                const cv = document.getElementById(`convictionInput`);
                if (va) decisions.value = va.value;
                if (ch) decisions.cheaper = ch.value;
                if (fe) decisions.feasible = fe.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, facultyDelta = 0, launchDelta = 0;
            let costAdd = 0;            // engagement cost added this round (€M)
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the real gap vs the brief's label (Common Error 1).
                if (d.gap === this.TRUE_GAP) {
                    fitDelta += 16; coachKey = `coach_r1_gap_right`;
                } else if (d.gap === `strategy` || d.gap === `presenting`) {
                    fitDelta -= 16; coachKey = `coach_r1_brief`;
                } else {
                    fitDelta -= 12; coachKey = `coach_r1_talent`;
                }

                // Anchor the diagnosis on triangulated evidence, not the one-pager.
                if (d.evidence === this.TRUE_EVIDENCE) {
                    fitDelta += 8;
                    if (d.gap === this.TRUE_GAP) coachKey = `coach_r1_diag_sharp`;
                } else if (d.evidence === `interviews`) {
                    fitDelta += 3;
                } else if (d.evidence === `brief`) {
                    fitDelta -= 10; coachKey = `coach_r1_evbrief`;
                } else {
                    fitDelta -= 4;
                }

                // 3–4 named behaviours is the discipline; too few vague, too many unfocused.
                if (d.behaviours >= 3 && d.behaviours <= 4) { fitDelta += 5; }
                else if (d.behaviours <= 1) { fitDelta -= 8; coachKey = `coach_r1_toofew`; }
                else if (d.behaviours >= 7) { fitDelta -= 6; coachKey = `coach_r1_toomany`; }

                // Impact metric: design backward from behaviour, not satisfaction (Common Error 5 seed).
                if (d.metric === this.TRUE_METRIC) { fitDelta += 4; }
                else if (d.metric === `satisfaction`) { fitDelta -= 8; coachKey = `coach_r1_satisfaction`; }

                summaryKey = (d.gap === this.TRUE_GAP && d.evidence === this.TRUE_EVIDENCE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                const star = d.star, aff = d.affiliate, cli = d.client;
                ds.starDays = star;

                // Format spine: a coherent blended journey wins; all-live is relevant but ruinously
                // expensive; mostly-digital scales but transfers behaviour weakly; lecture is generic.
                switch (d.format) {
                    case `blended`: fitDelta += 8; facultyDelta += 4; costAdd += 0.32; coachKey = `coach_r2_blended`; break;
                    case `alllive`: fitDelta += 4; facultyDelta -= 6; costAdd += 0.95; coachKey = `coach_r2_alllive`; break;
                    case `digital`: fitDelta -= 14; facultyDelta += 6; costAdd += 0.18; coachKey = `coach_r2_digital`; break;
                    case `lecture`: fitDelta -= 16; costAdd += 0.22; coachKey = `coach_r2_lecture`; break;
                }

                // Faculty mix & cost. Star days beyond the 24 that exist = over-promising (Error 2).
                costAdd += star * this.STAR_DAY_COST + aff * this.AFFILIATE_DAY_COST + cli * this.CLIENT_DAY_COST;
                if (star > this.STAR_DAYS_AVAILABLE) {
                    const over = star - this.STAR_DAYS_AVAILABLE;
                    facultyDelta -= Math.min(40, 8 + over * 1.5);
                    ds.overPromised = true;
                    coachKey = `coach_r2_overpromise`;
                } else if (star >= 8 && aff >= 20 && cli >= 8) {
                    // A deliverable, balanced mix: some star credibility, scalable affiliates,
                    // client execs lifting relevance and ownership.
                    fitDelta += 4; facultyDelta += 12;
                    if (d.format === `blended`) coachKey = `coach_r2_balanced`;
                } else if (star === 0) {
                    fitDelta -= 4; facultyDelta += 4; coachKey = `coach_r2_nostar`;
                } else {
                    facultyDelta += 4;
                }
                // Client execs as faculty lift relevance specifically.
                if (cli >= 8) fitDelta += 3;

                // Transfer mechanism: action learning changes behaviour on the job (L3-L4).
                switch (d.transfer) {
                    case `actionproject`: fitDelta += 8; costAdd += 0.20; if (d.format === `blended` && !ds.overPromised) coachKey = `coach_r2_transfer`; break;
                    case `coaching`: fitDelta += 5; costAdd += 0.12; break;
                    case `content`: fitDelta -= 6; costAdd += 0.06; coachKey = `coach_r2_content`; break;
                    case `none`: fitDelta -= 14; coachKey = `coach_r2_notransfer`; break;
                }

                summaryKey = (!ds.overPromised && d.format === `blended` && (d.transfer === `actionproject` || d.transfer === `coaching`)) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Build the engagement P&L: price (revenue) vs accumulated cost. Add the round-3
                // design/digital build, then compute margin and absorb the launch & impact fee.
                let designBuild = 0.26; // baseline design hours, logistics, digital build
                ds.price = d.price;

                // Launch compression (Common Error 4).
                switch (d.launchPlan) {
                    case `phased`: launchDelta += 36; costAdd += 0.06; coachKey = `coach_r3_phased`; break;
                    case `overtime`: launchDelta += 30; designBuild += 0.18; coachKey = `coach_r3_overtime`; break;
                    case `yes`: launchDelta += 6; facultyDelta -= 6; coachKey = `coach_r3_sayyes`; break;
                    case `pushback`: launchDelta -= 18; fitDelta -= 8; coachKey = `coach_r3_pushback`; break;
                }
                costAdd += designBuild;

                // Total engagement cost so far including this round.
                const totalCost = Math.round((ds.engagementCost + costAdd) * 1000) / 1000;
                // Contribution margin off the quoted price.
                ds.margin = (d.price > 0) ? Math.round((1 - totalCost / d.price) * 1000) / 10 : 0;

                // Price discipline (Common Error 3). Below cap & at/above floor is the win.
                if (d.price > this.BUDGET_CAP + 0.001) {
                    fitDelta -= 12; ds.overCap = true; coachKey = `coach_r3_overcap`;
                } else if (ds.margin < this.MARGIN_FLOOR) {
                    ds.belowFloor = true; fitDelta -= 4; coachKey = `coach_r3_belowfloor`;
                } else if (d.price <= this.BUDGET_CAP + 0.001 && ds.margin >= this.MARGIN_FLOOR) {
                    fitDelta += 3;
                    if (d.launchPlan === `phased`) coachKey = `coach_r3_disciplined`;
                }

                // Impact-linked fee: design measurement in vs gamble on satisfaction (Common Error 5).
                switch (d.impactFee) {
                    case `design`: fitDelta += 5; if ((state.decisions.transfer === `actionproject` || state.decisions.transfer === `coaching`)) { fitDelta += 2; } coachKey = (coachKey === `coach_r3_disciplined`) ? `coach_r3_disciplined` : `coach_r3_impactdesign`; break;
                    case `cap`: fitDelta += 2; break;
                    case `satisfaction`: fitDelta -= 12; coachKey = `coach_r3_satisfaction`; break;
                    case `reject`: fitDelta -= 8; coachKey = `coach_r3_rejectfee`; break;
                }

                // Scope discipline protects the margin against post-signature creep.
                if (d.scope >= 60) { ds.margin = Math.round((ds.margin + 1.5) * 10) / 10; }
                else if (d.scope <= 25) { ds.margin = Math.round((ds.margin - 4) * 10) / 10; fitDelta -= 2; coachKey = (ds.belowFloor || ds.overCap) ? coachKey : `coach_r3_scopecreep`; }

                // Record the scope-adjusted margin so the round-4 recompute does not silently drop it.
                ds.marginAdj = ds.margin;

                if (ds.margin < this.MARGIN_FLOOR) ds.belowFloor = true; else if (d.price <= this.BUDGET_CAP + 0.001) ds.belowFloor = false;

                summaryKey = (!ds.overCap && ds.margin >= this.MARGIN_FLOOR && d.launchPlan !== `yes`) ? `sum_r3_good` : (ds.belowFloor ? `sum_r3_discount` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch & defend (Common Errors 3 & 4 under live pressure).
                switch (d.value) {
                    case `diagnosis`: fitDelta += 4; coachKey = `coach_r4_diagnosis`; break;
                    case `names`: fitDelta += 2; facultyDelta -= 4; coachKey = `coach_r4_names`; break;
                    case `price`: fitDelta -= 8; coachKey = `coach_r4_leadprice`; break;
                }

                // Objection 1: the consultancy is 15% cheaper.
                switch (d.cheaper) {
                    case `value`: fitDelta += 4; coachKey = (d.value === `diagnosis`) ? `coach_r4_holdvalue` : coachKey; break;
                    case `match`:
                        // Dropping ~€250k blows the margin (Common Error 3).
                        ds.price = Math.round((ds.price - 0.25) * 100) / 100;
                        ds.discounted = true;
                        coachKey = `coach_r4_match`;
                        break;
                    case `trim`: fitDelta -= 10; coachKey = `coach_r4_trim`; break;
                }

                // Objection 2: can you really launch in 16 weeks?
                switch (d.feasible) {
                    case `phasedproof`: launchDelta += 12; fitDelta += 3; if (d.cheaper === `value` && d.value === `diagnosis`) coachKey = `coach_r4_strongclose`; break;
                    case `promise`: launchDelta -= 6; facultyDelta -= 6; coachKey = `coach_r4_promise`; break;
                    case `renegotiate`: launchDelta -= 16; fitDelta -= 6; coachKey = `coach_r4_renegotiate`; break;
                }

                // Conviction nudges fit.
                fitDelta += Math.round((d.conviction - 60) / 12);

                // Recompute margin off any discount taken in the pitch, preserving the
                // round-3 scope adjustment as a delta so it is not silently dropped.
                if (ds.price > 0) {
                    let m = Math.round((1 - ds.engagementCost / ds.price) * 1000) / 10;
                    if (ds.marginAdj != null) {
                        const undiscountedPrice = ds.discounted ? Math.round((ds.price + 0.25) * 100) / 100 : ds.price;
                        const r3base = Math.round((1 - ds.engagementCost / undiscountedPrice) * 1000) / 10;
                        m = Math.round((m + (ds.marginAdj - r3base)) * 10) / 10;
                    }
                    ds.margin = m;
                }
                if (ds.margin < this.MARGIN_FLOOR) ds.belowFloor = true;

                summaryKey = (d.value === `diagnosis` && d.cheaper === `value` && d.feasible === `phasedproof`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cost accounting (cumulative committed engagement cost).
            ds.engagementCost = Math.round((ds.engagementCost + costAdd) * 1000) / 1000;
            if (ds.engagementCost > this.BUDGET_CAP + 0.001) ds.overCap = true;

            // KPIs move on their deltas, bounded 0..100.
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.faculty = Math.max(0, Math.min(100, ds.faculty + facultyDelta));
            ds.launch = Math.max(0, Math.min(100, ds.launch + launchDelta));

            // Margin only computed/quoted from round 3 onward; before that hold the projected 35%.
            if (round < 3) {
                ds.margin = 35;
            } else {
                ds.margin = Math.max(-50, Math.min(80, ds.margin));
            }

            ds.fitHistory.push(Math.round(ds.fit));
            ds.marginHistory.push(Math.round(ds.margin));
            ds.facultyHistory.push(Math.round(ds.faculty));
            ds.launchHistory.push(Math.round(ds.launch));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                margin: Math.round(ds.margin),
                faculty: Math.round(ds.faculty),
                facultyDelta: Math.round(facultyDelta),
                launch: Math.round(ds.launch),
                launchDelta: Math.round(launchDelta),
                engagementCost: ds.engagementCost,
                price: ds.price,
                belowFloor: ds.belowFloor,
                overCap: ds.overCap,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

