        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Weights copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var fit = Math.round(ds.fit || 0);
            var margin = Math.round(ds.margin || 0);
            var faculty = Math.round(ds.faculty || 0);
            var launch = Math.round(ds.launch || 0);
            return Math.max(0, Math.min(100, Math.round(
                Math.max(0, Math.min(100, fit)) * 0.30 +
                Math.max(0, Math.min(100, margin * (100 / 50))) * 0.28 +
                faculty * 0.22 +
                launch * 0.20
            )));
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const margin = Math.round(ds.margin);
            const faculty = Math.round(ds.faculty);
            const launch = Math.round(ds.launch);

            const marginOk = margin >= this.MARGIN_FLOOR && !ds.overCap;
            const deliverable = faculty >= 55 && !ds.overPromised;
            const onTime = launch >= 55;
            const relevant = fit >= 65;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_lost`;
            if (relevant && marginOk && deliverable && onTime && composite >= 70) performanceKey = `grade_won_right`;
            else if (relevant && marginOk && deliverable && onTime) performanceKey = `grade_credible`;
            else if (relevant && !marginOk) performanceKey = `grade_marginblown`;
            else if (relevant && marginOk && (!deliverable || !onTime)) performanceKey = `grade_undeliverable`;
            else if (fit > 50) performanceKey = `grade_short`;
            const performance = T(performanceKey);

            const insights = [];
            if (relevant && marginOk && deliverable && onTime) insights.push(window.mySimulation.t(`insight_won`));
            else if (relevant && !marginOk) insights.push(window.mySimulation.t(`insight_marginblown`));
            else if (relevant && (!deliverable || !onTime)) insights.push(window.mySimulation.t(`insight_undeliverable`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (ds.belowFloor || margin < this.MARGIN_FLOOR) insights.push(window.mySimulation.t(`insight_belowfloor`));
            if (ds.overCap) insights.push(window.mySimulation.t(`insight_overcap`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (launch < 45) insights.push(window.mySimulation.t(`insight_launch`));
            if (relevant && marginOk && deliverable && onTime && margin >= 38) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                fit: fit,
                margin: margin,
                faculty: faculty,
                launch: launch,
                marginOk: marginOk,
                deliverable: deliverable,
                onTime: onTime,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                won: (relevant && marginOk && deliverable && onTime),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var won = !!s.won;
            var badge = won
                ? '<span class="customprog-cm-badge customprog-cm-yes">' + T('cm_won') + '</span>'
                : '<span class="customprog-cm-badge customprog-cm-no">' + T('cm_lost') + '</span>';
            var marginBadge = (s.marginOk === false)
                ? '<span class="customprog-cm-badge customprog-cm-warn">' + T('cm_margin_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="customprog-cm-metric"><span class="customprog-cm-mv">' + Math.round(s.fit || 0) + '</span><span class="customprog-cm-ml">' + T('cm_m_fit') + '</span></div>'
                + '<div class="customprog-cm-metric"><span class="customprog-cm-mv">' + Math.round(s.margin || 0) + '%</span><span class="customprog-cm-ml">' + T('cm_m_margin') + '</span></div>'
                + '<div class="customprog-cm-metric"><span class="customprog-cm-mv">' + Math.round(s.faculty || 0) + '</span><span class="customprog-cm-ml">' + T('cm_m_faculty') + '</span></div>'
                + '<div class="customprog-cm-metric"><span class="customprog-cm-mv">' + Math.round(s.launch || 0) + '</span><span class="customprog-cm-ml">' + T('cm_m_launch') + '</span></div>';
            return ''
                + '<div class="customprog-completion">'
                +   '<div class="customprog-cm-head">'
                +     '<div class="customprog-cm-score">' + score + '<span class="customprog-cm-score-max">/100</span></div>'
                +     '<div class="customprog-cm-grade">' + grade + ' ' + badge + marginBadge + '</div>'
                +   '</div>'
                +   '<div class="customprog-cm-metrics">' + metrics + '</div>'
                +   '<div class="customprog-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="customprog-cm-insights">' + items + '</ul>'
                + '</div>';
        }

